"""Render lab/docs/ANALYTICS-*.md from the committed results files, so every figure in the docs is script-generated.

    cd lab && python -m analytics.run_all && python -m analytics.render_docs
A test re-renders and compares with the committed docs. SYNTHETIC DATA / SIMULATED OPERATION / NOT PRODUCTION DEPLOYED.
"""
import json
import os

LAB = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
RES = os.path.join(LAB, "results", "analytics")
DOCS = os.path.join(LAB, "docs")
BANNER = "**SYNTHETIC DATA / SIMULATED OPERATION / NOT PRODUCTION DEPLOYED.** NASHA has no restaurant, customers, sales, suppliers or staff. Prices, costs and recipes are placeholders or assumptions. Nothing here is a business result."


def R(name):
    with open(os.path.join(RES, name + ".json"), encoding="utf-8") as f:
        return json.load(f)


def table(headers, rows):
    out = ["| " + " | ".join(headers) + " |", "|" + "|".join("---" for _ in headers) + "|"]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)


def pct(x, d=1): return f"{100 * x:.{d}f}%"
def f2(x, d=2): return f"{x:.{d}f}"


# ---------------------------------------------------------------------------------------------------------------- ANALYTICS-MART.md
def render_mart():
    ms = R("mart_summary"); mr = R("metrics_reconciliation"); sq = R("sql_library")
    rc = ms["row_counts"]
    fact_rows = [(t, f"{rc[t]:,}") for t in sorted(rc) if t.startswith("fact_")]
    dim_rows = [(t, f"{rc[t]:,}") for t in sorted(rc) if t.startswith(("dim_", "bridge_"))]
    return f"""# NASHA analytics mart (P4): design and how to run

{BANNER}

A reproducible star schema, metric layer, SQL library, data-quality framework, forecasting backtest and simulated experiment, built from the lab's synthetic generator. Additive: nothing in the frozen Block 3 evidence was changed. Evaluation numbers are in [ANALYTICS-EVALUATION](ANALYTICS-EVALUATION.md); the decision memo is [ANALYTICS-EXEC-MEMO](ANALYTICS-EXEC-MEMO.md).

## Where the data comes from (provenance)

| Layer | Source | Status |
|---|---|---|
| Sites, menu (v1 and v2), orders, order lines, inventory counts, injected defects with labels | `nasha_lab/generator.py` and `pipeline.py` (the lab, seed {ms['seed']}) | generated by the lab; defect labels are ground truth |
| SCD2 menu change (v1 `Gobi Taco` to v2 `Mango Habanero Gobi`, internal id `M04`) | `analytics/mart.py` | the lab models menu versions as whole-world alternatives; a dated change on **{ms['menu_change_date_assumption']} is a SYNTHETIC SCENARIO DATE / DESIGN ASSUMPTION** of this package so orders exist on both sides. It is not a real menu-change date: no NASHA source proves one (searched `lab/` and the repository docs; D-84, dated 2026-10-15, records a design direction, not an effective date) |
| Inventory snapshots, receipts, purchase-order history, logged waste, supplier lateness, unlogged shrink | `analytics/synth.py` (seeded) | **SIMULATED** by this package with parameters in `analytics/config.py`; the lab's 3 scenario POs are not loaded |
| Guests (cohorts, retention, experiment) | `analytics/synth.py` | **SIMULATED**; NASHA has no guests |
| Exception approval and resolution times | `analytics/synth.py` | **SIMULATED**; detection of the exception itself is derived from the mart |
| Prices | lab generator | placeholder inputs |
| Ingredient costs, other-cost percentages, fixed unit costs | `analytics/config.py` | **ASSUMPTIONS**, one file, labelled |

## Star schema (text diagram)

```
                               dim_date            dim_site            dim_channel
                                  |                   |                    |
dim_guest(SYNTH) --- fact_order (grain: accepted order) ---------------------+
                          |
dim_menu_item (SCD2) --- fact_order_line (grain: order line) --- dim_site, dim_date, dim_channel, dim_guest
        |
bridge_item_ingredient (recipe per item VERSION) --> dim_ingredient <-- fact_usage_daily (site x ingredient x date, derived)
                                                          |
                    fact_inventory_snapshot (site x ingredient x weekly count) -- dim_site, dim_date
                    fact_po_line (PO line) -- dim_supplier, dim_site, dim_ingredient, dim_date (order / expected / received)
                    fact_waste_adjustment (event) -- dim_waste_reason, dim_site, dim_ingredient, dim_date
                    fact_quality_finding (lab DQ finding) -- dim_dq_rule, dim_site
                    fact_exception_event (inventory exception workflow, SIMULATED stages)
```

Conformed dimensions: date, site, menu item, supplier, ingredient (shared by several facts). Surrogate keys everywhere; key 0 is the Unknown member of each dimension so facts never lose rows. Full DDL and grain comments: `lab/analytics/sql/ddl.sql`.

### Grain and size of this build

{table(["Fact", "Grain", "Rows"], [
 ("fact_order", "one accepted order", f"{rc['fact_order']:,}"),
 ("fact_order_line", "one accepted order line (order_id, line_no)", f"{rc['fact_order_line']:,}"),
 ("fact_usage_daily", "site x ingredient x date (sparse; zero days absent)", f"{rc['fact_usage_daily']:,}"),
 ("fact_inventory_snapshot", "site x ingredient x weekly count date", f"{rc['fact_inventory_snapshot']:,}"),
 ("fact_po_line", "purchase-order line", f"{rc['fact_po_line']:,}"),
 ("fact_waste_adjustment", "waste or count-adjustment event", f"{rc['fact_waste_adjustment']:,}"),
 ("fact_quality_finding", "one lab DQ finding (incl. quarantined rows)", f"{rc['fact_quality_finding']:,}"),
 ("fact_exception_event", "one inventory exception", f"{rc['fact_exception_event']:,}")])}

Dimensions: {", ".join(f"{t} ({n})" for t, n in dim_rows)}.

### SCD Type 2 (menu item)

`dim_menu_item` has one row per (item_id, version) with `valid_from` inclusive and `valid_to` exclusive; open rows end `9999-12-31`; exactly one `is_current` row per item. Facts carry the **version in effect on the order date** (`item_key`), so the old name stays on old orders. Tests check no gaps, no overlaps, one current row and that every order line falls inside its version window ({ms['order_lines_outside_scd2_window']} violations in this build).

## Semantic layer

`lab/analytics/metrics.json` defines {len(mr['rows'])} metrics (name, grain, formula, owner role, caveats, mart SQL and an independent source-side definition). `analytics/metrics.py` evaluates both and `tests/test_analytics_metrics.py` requires them to agree. Reconciliation in this build: **{sum(r['ok'] for r in mr['rows'])} of {len(mr['rows'])} metrics reconcile** (largest absolute difference {max(r['max_abs_diff'] for r in mr['rows']):.2e}). Ratio metrics are marked non-additive.

## Structural checks (this build)

- Row-count reconciliation: {sum(v['equal'] for v in ms['reconciliation'].values())} of {len(ms['reconciliation'])} equalities hold (raw rows = modeled + quarantined, source = mart, gross sales and order totals in cents, PO receipts = snapshot receipts).
- Referential integrity: {sum(1 for v in ms['orphan_foreign_keys'].values() if v)} foreign keys with orphans out of {len(ms['orphan_foreign_keys'])} checked.
- Grain uniqueness: {sum(1 for v in ms['grain_duplicates'].values() if v)} tables with duplicate grain rows out of {len(ms['grain_duplicates'])} checked.

## SQL library and difficult cases

- `lab/analytics/sql/library/Q01..Q{len(sq['queries']):02d}`: {sq['count']} documented queries (question, technique, expected shape, SQLite-specific notes), each with a test in `tests/test_analytics_sql_library.py`.
- `lab/analytics/difficult_cases/01..10`: ten trap cases, each with candidate-facing `prompt.md`, `fixture.sql` and `trap.sql`. The answer keys are **private and not in this repository**; the cases are verified only when the environment variable `NASHA_PRIVATE_KEYS` points at the private key directory (tests that need keys SKIP otherwise). A sha256 manifest of the removed key files is committed (`difficult_cases/KEYS-MANIFEST.sha256`); see `difficult_cases/README.md`.

## How to run

```bash
cd lab
python3 -m analytics.mart --db /tmp/nasha_mart.sqlite     # build the mart (seed 1) and print row counts
python3 -m analytics.run_all                              # regenerate every file in lab/results/analytics/ (~1 minute)
python3 -m analytics.render_docs                          # re-render the ANALYTICS-*.md docs and the dashboard from those files
python3 -m pytest -q -p no:cacheprovider tests/test_analytics_*.py
python3 -m pytest -q -p no:cacheprovider tests            # full suite (about 2 minutes)
```

Everything is seeded; `config.py` holds every assumption and `config_hash` is stamped in each results file. SQLite is the engine (3.45 here); DDL and loads are portable SQL, with SQLite-specific `date()`, `julianday()`, `GROUP_CONCAT`, `rowid` and `ATTACH`-free `backup()` noted in the query headers. Dependencies beyond the lab's: none (numpy and scipy come with scikit-learn).

## Dashboard

`lab/results/analytics/dashboard.html`: static, no CDN, rendered from the results JSON by `analytics/render_docs.py`. Read-only; screenshot-checked with Playwright (see ANALYTICS-EVALUATION).
"""


# ---------------------------------------------------------------------------------------------------------------- ANALYTICS-EVALUATION.md
def render_eval():
    ms, mr, sq, dc = R("mart_summary"), R("metrics_reconciliation"), R("sql_library"), R("difficult_cases")
    dq, fc, ex, ms2, rc = R("dq_evaluation"), R("forecast_backtest"), R("experiment"), R("margin_sensitivity"), R("recovery_checks")
    L = []
    a = L.append
    a(f"# NASHA analytics mart: evaluation\n\n{BANNER}\n\nEvery figure below is read from `lab/results/analytics/*.json` by `analytics/render_docs.py`. Same-author caveat: one author wrote the generator, the injected defects, the simulations, the rules and this evaluation; there is no independent review.\n")
    a("## 1. Mart integrity\n")
    a(f"Reconciliation equalities holding: {sum(v['equal'] for v in ms['reconciliation'].values())} of {len(ms['reconciliation'])}. Orphan foreign keys: {sum(v for v in ms['orphan_foreign_keys'].values())}. Duplicate grain rows: {sum(ms['grain_duplicates'].values())}. SCD2 problems: {len(ms['scd2_problems'])}. Order lines outside their SCD2 window: {ms['order_lines_outside_scd2_window']}.\n")
    a(table(["Check", "Left", "Right", "Equal"], [(k, v["left"], v["right"], v["equal"]) for k, v in ms["reconciliation"].items()]))
    a("\n## 2. Metric reconciliation (semantic layer)\n")
    a(f"{sum(r['ok'] for r in mr['rows'])} of {len(mr['rows'])} metrics agree between the mart definition and an independent source-side definition (tolerance 1e-6).\n")
    a(table(["Metric", "Groups", "Max abs difference", "OK"], [(r["metric"], r["groups"], f"{r['max_abs_diff']:.1e}", r["ok"]) for r in mr["rows"]]))
    a("\nCaveat: for the metrics whose source-side definition is Python (usage, margin, waste, count variance, supplier timing) the Python re-derives from the same seeded simulation, so agreement checks the SQL load path, not the realism of the simulation.\n")
    a(f"\n## 3. SQL library ({sq['count']} queries) and difficult cases ({dc['count']})\n")
    a(table(["Id", "Title", "Rows returned"], [(q["id"], q["title"], q["rows"]) for q in sq["queries"]]))
    a("\nEach query has a test comparing its output with an independent Python or SQL computation (`tests/test_analytics_sql_library.py`). Findings from writing them:\n")
    a("- **Q08 (basket affinity): every pair lift is below 1 (0.8 to 1.0).** There is no planted affinity. The generator draws 1 to 4 *distinct* items per order, which mechanically lowers every pair's co-occurrence. This is a sampling artifact, not substitution behaviour; reading it as 'cannibalisation' would be wrong.")
    a("- **Q06 first draft returned a share of 1.0 for the renamed dish** because the `WHERE item_id='M04'` sat in the same SELECT as the window, shrinking the window's partition. The committed query computes shares in a CTE before filtering. This is one of the traps worth testing for.")
    a("- Q09 (cohort retention) and Q10 (funnel) run on SIMULATED guests and SIMULATED approval stages; their numbers describe the simulation processes only.\n")
    a("\nThe ten difficult-case answer keys are private (not in this repository). Public check only: each fixture loads and each candidate-facing trap query executes. Correctness of the keys is verified privately when `NASHA_PRIVATE_KEYS` is set.\n")
    a(table(["Difficult case", "Trap query executes", "Trap rows returned", "Private key files removed (sha256 in manifest)"], [(c["case"], c["trap_query_executes"], c["trap_rows_returned"], len(c["removed_private_key_files"])) for c in dc["cases"]]))
    # DQ
    sc = dq["score"]
    a(f"\n## 4. Data-quality framework: detection of injected defects\n\nSQL rules over the raw landing zone (`analytics/dqf.py`), {len(sc['per_rule'])} rules across completeness, validity, timeliness, uniqueness, consistency, referential integrity, range and policy; freshness and row-conservation are dataset-level checks. Scored on seeds {sc['seeds'][0]} to {sc['seeds'][-1]}, {sc['defects_per_type']} injected defects per type per seed.\n")
    a(table(["Defect type (injected)", "Found by any rule", "Total", "Recall (framework)", "Recall (lab `dq.py`)"],
            [(t, v["found"], v["total"], f2(v["recall"], 3), f2(dq["lab_rules_for_comparison"][t]["recall"], 3)) for t, v in sc["per_defect_type_any_rule_recall"].items()]))
    a("\nPer rule against its target defect type (precision counts every flag that is not a labelled defect of the target type; `other` = the flag is a different injected defect, `clean` = a flag on a row with no injected defect):\n")
    a(table(["Rule", "Target", "TP", "FP other", "FP clean", "FN", "Precision", "Recall"],
            [(k, v["targets"] or "(control)", v["tp"], v["fp_other_injected_defect"], v["fp_clean_row"], v["fn"], "-" if v["precision"] is None else f2(v["precision"], 3), "-" if v["recall"] is None else f2(v["recall"], 3)) for k, v in sc["per_rule"].items()]))
    cl = dq["clean_data_false_alarms"]
    a(f"\n- **Clean data (no injected defects), seeds 1 to 5:** {cl['total_flags']} flags over {cl['orders_scanned']:,} orders.")
    fr = dq["freshness"]
    a(f"- Freshness: newest valid order {fr['newest_valid_order_date']} vs as-of {fr['as_of']} = {fr['age_days']} days (limit {fr['max_age_days']}): {'pass' if fr['ok'] else 'FAIL'}. The as-of is the generator's scenario date, so this passes by construction.")
    a(f"- Row conservation through the lab pipeline (raw = modeled + quarantined): {all(v['ok'] for v in dq['row_conservation'].values())}.")
    a(f"\n**Honest reading.** Recall is 1.0 for all twelve types because the injected defects are simple, labelled by the same author, and the rules were written for them. Two things deserve candour: (1) the lab's own rules find {dq['lab_rules_for_comparison']['near_duplicate_shifted']['found']} of {dq['lab_rules_for_comparison']['near_duplicate_shifted']['total']} `near_duplicate_shifted` copies (they are shifted by one second); the framework catches them with a 2-second tolerance rule (UNIQ-03) that I added after seeing that miss, so it is *not* a blind result; (2) UNIQ-03 also flags the exact-timestamp copies, so its precision against its own target is 0.5 (no clean rows are flagged). The price rule flags 3 lines that are orphan items (a cross-flag, not a clean-row false alarm).\n")
    p = dq["novel_defect_probe"]
    a("Defects the generator does *not* inject, planted by `dqf.novel_probe` without tuning any rule to them:\n")
    a(table(["Planted defect kind", "Planted", "Detected"], [(k, v["planted"], v["detected"]) for k, v in p.items()]))
    a("\nThe 5-hour timezone slip is structurally valid and **no rule can see it**. Duplicated lines and x100 quantities are detected only because the planted header total was left unchanged (consistency rule); a consistent forgery would pass. Real data would present many defect kinds that none of this has been exposed to.\n")
    # recovery
    sh = rc["unlogged_shrink_recovery"]; lt = rc["late_supplier_recovery"]
    a("## 5. Do the mart analyses recover what the simulation injected?\n")
    a(f"- **Unlogged shrink (L03 goat, 6% of usage, no waste entry):** observed net count variance {pct(sh['observed_variance_pct_of_usage'])} of usage. Rank among all {sh['pairs_total']} site x ingredient pairs by most negative variance: **{sh['rank_most_negative_all_24_pairs']}** (the top pair is L03 hops at {pct(sh['most_negative_five_all'][0][2])} on only {sh['most_negative_five_all'][0][3]} kg of usage: small-quantity noise, a false lead). Among pairs with at least 20 kg usage: rank **{sh['rank_most_negative_pairs_with_usage_ge_20kg']}** of {sh['pairs_with_usage_ge_20kg']}; across seeds 1 to 5 the rank is {', '.join(str(m['rank_of_L03_goat_among_pairs_ge_20kg']) for m in sh['multi_seed_rank_pairs_ge_20kg'])}. A volume floor is needed to find it; without one the top hit is noise.")
    a(f"- **Unreliable suppliers (injected late probability S03 0.40, S05 0.25, others at most 0.10):** observed on-time order worst first: {', '.join(f'{s} {r:.2f} (n={n})' for s, r, n in lt['observed_on_time_rate_worst_first'])}. The two worst match the injected two: {lt['worst_two_match_injected_worst_two']}. Sample sizes are 21 to 39 lines per supplier, so the middle of the ranking is not reliable.")
    ma = rc["corn_masa_kg_per_day_before_after_recipe_change"]
    ms_date = R("mart_summary")["menu_change_date_assumption"]
    a(f"- **About the menu-change date.** {ms_date} is a **SYNTHETIC SCENARIO DATE / DESIGN ASSUMPTION** chosen so orders exist on both sides of the SCD2 change inside the 56-day window. It is not a real menu-change date. No existing NASHA source proves one: a search of `lab/` and the repository docs found only D-84 (2026-10-15), which records the design direction (Mango Habanero Gobi, an appetizer, replacing the Gobi Taco concept) and no effective date; nothing has been cooked or sold.")
    a(f"- **Recipe change through SCD2:** corn masa theoretical usage {ma[0][1]} kg/day (all sites) before the SYNTHETIC SCENARIO DATE {ms_date} (design assumption, not a real date) and {ma[1][1]} kg/day after, because the v2 dish drops the tortilla. The SCD2 as-of join is what makes this appear.\n")
    # margin
    a("## 6. Contribution margin (ASSUMPTION costs) and its sensitivity\n")
    base = ms2["ranking_by_multiplier"]["1.0"]
    a(table(["Item version", "Units", "Sales (USD, placeholder prices)", "Margin (USD, assumed costs)", "Margin per unit (USD)"], [(x["item"], x["units"], f"{x['sales_usd']:,.0f}", f"{x['margin_usd']:,.0f}", f2(x["margin_usd"] / x["units"])) for x in base]))
    a(f"\nUniform +/-25% change in all assumed costs: ranking identical across multipliers = **{ms2['ranking_identical_across_multipliers']}**; top three identical = **{ms2['top3_identical_across_multipliers']}**. Why this can or cannot be invariant: with uniform multiplier m each item has margin_i(m) = S_i - m*C_i (sales S_i, assumed cost C_i), a straight line in m, so two items swap rank exactly when m = (S_i - S_j)/(C_i - C_j) lies inside the tested range. A uniform scaling does NOT structurally preserve the ranking (it would only if the cost-to-sales ratio were identical across items); the flags above are measured results, not guarantees. The ordering by *total* margin is also driven by exposure (the pre-change `Gobi Taco` version has six weeks of sales, `Mango Habanero Gobi` two), so compare per-unit margin. Margins of 70 to 80% for food reflect that labour, rent, overhead and waste cost are **excluded**; this is an illustration of the calculation, not a margin NASHA would earn.\n")
    # forecast
    a("## 7. Forecast backtest (rolling origin)\n")
    d = fc["design"]
    a(f"Series: theoretical daily usage per site x ingredient (24 per seed) for seeds {d['seeds']}. Expanding window, forecast horizon {d['horizon_days']} days, origins at days {d['origins']} (minimum {d['min_train_days']} training days), {fc['overall']['naive']['n_forecasts']} seven-day forecasts per model. **The data are synthetic, so these accuracies say nothing about real demand.**\n")
    a(table(["Model", "MAE (kg)", "WAPE", "MAPE % (non-zero days)", "Bias % of actual", "WAPE vs naive (95% CI)", "WAPE vs seasonal naive (95% CI)", "80% interval coverage"],
            [(m, f2(v["MAE"], 3), f2(v["WAPE"], 3), f2(v["MAPE_pct_nonzero_days"], 1), f2(v["bias_pct_of_actual"], 1),
              "baseline" if m == "naive" else f"{fc['paired_vs_naive'][m]['wape_diff_vs_naive']:+.3f} [{fc['paired_vs_naive'][m]['ci95'][0]:+.3f}, {fc['paired_vs_naive'][m]['ci95'][1]:+.3f}]",
              "baseline" if m == "seasonal_naive" else f"{fc['paired_vs_seasonal_naive'][m]['wape_diff_vs_seasonal_naive']:+.3f} [{fc['paired_vs_seasonal_naive'][m]['ci95'][0]:+.3f}, {fc['paired_vs_seasonal_naive'][m]['ci95'][1]:+.3f}]",
              f2(fc["interval_80"][m]["empirical"], 3)) for m, v in fc["overall"].items()]))
    nv, sn, best = fc["overall"]["naive"]["WAPE"], fc["overall"]["seasonal_naive"]["WAPE"], fc["best_by_wape"]
    a(f"\n- Best by WAPE: **{best}** at {fc['overall'][best]['WAPE']:.3f} versus {nv:.3f} for last-value naive ({pct(1 - fc['overall'][best]['WAPE'] / nv, 0)} lower) and {sn:.3f} for seasonal naive. Differences among the four smoothing models are small compared with the gap to naive; the intervals above were computed only against the two naive baselines, so do not read the ranking among the smoothers as established.")
    a(f"- **Surprise:** seasonal naive (copy the same weekday last week) is much worse than a plain 7-day average. Daily ingredient usage is dominated by random basket composition, and the weekday effect (Friday to Sunday x1.3 orders) is small relative to that noise. Seasonal naive wins on only {pct(fc['paired_vs_naive']['seasonal_naive']['win_rate_units'], 0)} of units against naive.")
    cv = [v["empirical"] for v in fc["interval_80"].values()]
    a(f"- **Intervals:** a normal interval from in-sample one-step errors was nominal 80%; empirical coverage is in the last column ({min(cv):.2f} to {max(cv):.2f}), so calibration is acceptable on this synthetic data. It would not be assumed on real data.")
    a("- Bias is positive for naive (it follows the last day, including the Friday to Sunday peak). Hops and malt are identical series up to scale, which inflates the apparent number of independent series; origins within one series are also not independent, so the bootstrap intervals are optimistic.")
    rcn = fc["recipe_change_note"]["origin_49_corn_masa_wape"]
    a(f"- Corn masa contains a structural break (recipe change). WAPE at the last origin: {', '.join(f'{k} {v:.3f}' for k, v in rcn.items())}. No model was given the break; this is the case where a metric definition change, not a forecaster, matters most.\n")
    # experiment
    a("## 8. Synthetic experiment: does the analysis recover the injected effect?\n")
    dn = ex["design"]; sr = ex["single_run"]["m04_units"]; mc = ex["monte_carlo_with_effect"]; nl = ex["monte_carlo_null_AA"]
    a(f"{ex['disclaimer']} Unit: synthetic guest; {dn['guests']} guests ({dn['treated']} treated, {dn['control']} control; SRM chi-square p = {ex['srm_chi2_p']:.2f}). Effect injected: {dn['injected_effect']}. Primary metric: {dn['primary_metric']}. Guardrails / negative controls (true effect zero): {', '.join(dn['guardrails_negative_controls'])}. Multiplicity: {dn['multiplicity']}.\n")
    pw = ex["power_plan"]; tr = ex["truth"]
    need = 2 * (1.96 + 0.8416) ** 2 * pw["pre_period_sd_m04_units"] ** 2 / tr["m04_units_per_treated_guest"] ** 2
    a(f"**A-priori power.** Pre-period sd of M04 units per guest = {pw['pre_period_sd_m04_units']:.2f}; with {pw['per_arm']:.0f} guests per arm the minimum detectable effect (80% power, alpha 0.05, unadjusted) is **{pw['mde_unadjusted_units']:.2f} units per guest**. The injected truth is **{tr['m04_units_per_treated_guest']:.3f}** units per treated guest, well below the MDE. About {need:,.0f} guests per arm would be needed for 80% power at that effect. The design is **underpowered by construction**; I left it that way to report the consequence. It is kept unchanged as historical evidence and is **not retroactively resized**. A separate prospective sample-size design (80% and 90% power, unadjusted and CUPED, with a Monte Carlo confirmation and a sensitivity table) is in [`ANALYTICS-PROSPECTIVE-DESIGN.md`](ANALYTICS-PROSPECTIVE-DESIGN.md).\n")
    a(table(["Estimator (primary metric)", "Estimate", "95% CI", "p", "CI contains truth"], [(k, f"{sr[k]['est']:.3f}", f"[{sr[k]['ci95'][0]:.3f}, {sr[k]['ci95'][1]:.3f}]", f"{sr[k]['p']:.3f}", ex["primary_ci_contains_truth"][k]) for k in ("unadjusted", "cuped", "stratified")]))
    a(f"\nSingle run (truth {tr['m04_units_per_treated_guest']:.3f}): the estimates overshoot the truth and are nominally significant at 0.05 in an experiment with about {pct(mc['metrics']['m04_units']['unadjusted']['reject_rate'], 0)} power: the classic winner's-curse situation. CUPED variance reduction on the primary metric is only {pct(sr['cuped']['var_reduction'])} (pre/post correlation {sr['pre_post_corr']:.2f}): **CUPED is not justified here**; guests' short pre-periods carry little information.\n")
    a(f"**Repeated randomisation + injection ({mc['reps']} reps) on this guest panel:**\n")
    rows = []
    for k in ("unadjusted", "cuped", "stratified"):
        m = mc["metrics"]["m04_units"][k]; n0 = nl["metrics"]["m04_units"][k]
        rows.append((k, f"{m['mean_est']:.3f}", f"{m['bias']:+.3f}", f"{m['sd_est']:.3f}", pct(m["ci_coverage"]), pct(m["reject_rate"]), pct(n0["reject_rate"])))
    a(table(["Estimator", "Mean estimate (truth %.3f)" % mc["truth"]["m04_units"], "Bias", "SD of estimate", "95% CI coverage", "Power (reject rate)", "A/A false-positive rate"], rows))
    a(f"\nThe analysis **recovers the injected effect without bias and with near-nominal coverage**; power at this effect size is {pct(mc['metrics']['m04_units']['unadjusted']['reject_rate'], 0)} (unadjusted), CUPED/stratification changing it by only a few points. Guardrail family (3 metrics, true effect zero): chance of at least one false positive is {pct(mc['guardrail_family_any_false_positive']['raw_alpha_0.05'])} uncorrected vs {pct(mc['guardrail_family_any_false_positive']['holm_0.05'])} with Holm (A/A: {pct(nl['guardrail_family_any_false_positive']['raw_alpha_0.05'])} vs {pct(nl['guardrail_family_any_false_positive']['holm_0.05'])}).\n")
    a("**Process note (a failure caught by this check).** My first version of the experiment code indexed the wrong column, so the 'primary metric' was actually orders per guest. The Monte Carlo recovery check showed a bias of minus the injected effect and a large false effect on 'orders'; fixing the column mapping gave the results above. A recovery test on a known injected effect is the reason that was found.\n")
    a("**Causal limitations (what this cannot show):**\n")
    a("\n".join(f"- {x}" for x in ex["causal_limitations"]))
    a("\n## 9. Failures, surprises, and limits\n")
    a("- Lab DQ rules miss every one-second-shifted near-duplicate; the new rule that catches them was written after seeing that.")
    a("- Net count variance for tiny-quantity ingredients (hops) is noisy and produced the top false lead for the injected shrink.")
    a("- Seasonal naive lost to a plain moving average; the generator's weekday signal is weak against basket noise.")
    a("- The synthetic experiment is underpowered at its injected effect, CUPED barely helps, and the one observed run overstates the effect.")
    a("- Q08 lifts below 1 are a generator artifact; Q06's first draft had a window-before-filter bug; the experiment code's first draft had a column-mapping bug.")
    a("- Contribution-margin ordering by total margin is exposure-driven for the SCD2 dish; costs are assumptions.")
    a("- Everything in sections 5 to 8 uses simulations whose parameters are in `analytics/config.py`; agreement with them shows the analysis code works, not that the world behaves that way.\n")
    a("## 10. Dashboard check\n")
    a("`lab/results/analytics/dashboard.html` is static and has no external requests. See the screenshot check recorded in `lab/results/analytics/dashboard_check.json` (generated by `analytics/dashboard_check.js`).\n")
    return "\n".join(L) + "\n"


# ---------------------------------------------------------------------------------------------------------------- ANALYTICS-EXEC-MEMO.md
def render_prospective():
    pd = R("prospective_design"); i = pd["inputs"]; h = pd["historical_experiment"]
    plan = pd["plan"]
    get = lambda p, e: next(x for x in plan if x["target_power"] == p and x["estimator"] == e)
    sens_rows = [(x["effect_multiplier"], f"{x['effect_units_per_guest']:.3f}", x["sd_multiplier"], f"{x['sd']:.2f}", f"{x['n_per_arm_unadjusted_80']:,}", f"{x['n_per_arm_cuped_80']:,}", f"{x['n_per_arm_unadjusted_90']:,}", f"{x['n_per_arm_cuped_90']:,}") for x in pd["sensitivity"]]
    return f"""# NASHA analytics: prospective sample-size design (synthetic experiment)

{BANNER}

This is a **forward-looking design exercise** for the simulated M04 placement test in [`ANALYTICS-EVALUATION.md`](ANALYTICS-EVALUATION.md). The original experiment there was **deliberately underpowered** ({h['per_arm']:.0f} synthetic guests per arm, analytic power about {pct(h['analytic_power_unadjusted'], 0)} at the injected effect). It is kept **unchanged as historical evidence and is NOT retroactively resized**. Nothing below is a real-business outcome: NASHA has no guests, no placement test and no sales.

## Inputs (from the simulated experiment)

- Injected effect: **{i['injected_effect_units_per_treated_guest']:.4f}** M04 units per treated guest. Pre-period SD of M04 units per guest: **{i['pre_period_sd_m04_units']:.4f}**. Observed pre/post correlation (for CUPED): **{i['observed_pre_post_corr']:.4f}**.
- Two-sided test, alpha {i['alpha_two_sided']}; two equal arms. Source: `results/analytics/experiment.json`; module `analytics/prospective_design.py`; results `results/analytics/prospective_design.json`.

## Required guests per arm

Closed form: n = 2 (z(1-alpha/2) + z(power))^2 sd^2 / delta^2; CUPED replaces sd^2 by sd^2 (1 - rho^2).

{table(["Target power", "Estimator", "n per arm", "Total", "Analytic power at n", "Monte Carlo power at n", "MC standard error", "Reaches target within MC error"], [(pct(x['target_power'], 0), x['estimator'], f"{x['n_per_arm']:,}", f"{x['n_total']:,}", pct(x['analytic_power_at_n'], 2), pct(x['monte_carlo_power_at_n'], 2), pct(x['monte_carlo_se'], 2), x['reaches_target_within_mc_error']) for x in plan])}

Headline: about **{get(0.8, 'unadjusted')['n_per_arm']:,} per arm for 80% power** and **{get(0.9, 'unadjusted')['n_per_arm']:,} per arm for 90% power** unadjusted; with CUPED at the observed correlation **{get(0.8, 'cuped')['n_per_arm']:,}** and **{get(0.9, 'cuped')['n_per_arm']:,}**. That is roughly {get(0.8, 'unadjusted')['n_per_arm'] / h['per_arm']:.1f} times the {h['per_arm']:.0f} per arm of the original run. CUPED saves only about {pct(1 - get(0.8, 'cuped')['n_per_arm'] / get(0.8, 'unadjusted')['n_per_arm'], 0)} because the correlation is low.

Type I error check at the 80% sample sizes with zero true effect: unadjusted {pct(pd['type_I_error_at_planned_n_80']['unadjusted'], 2)}, CUPED {pct(pd['type_I_error_at_planned_n_80']['cuped'], 2)} (nominal 5%).

## Sensitivity to effect size and SD (per arm)

{table(["Effect x", "Effect (units/guest)", "SD x", "SD", "80% unadj.", "80% CUPED", "90% unadj.", "90% CUPED"], sens_rows)}

CUPED correlation sensitivity at the injected effect and SD:

{table(["rho", "n per arm, 80%", "n per arm, 90%"], [(x['rho'], f"{x['n_per_arm_80']:,}", f"{x['n_per_arm_90']:,}") for x in pd['cuped_rho_sensitivity']])}

## Assumptions and limits

{chr(10).join('- ' + a_ for a_ in pd['assumptions'])}

Evidence: `lab/results/analytics/prospective_design.json`, reproducible with `cd lab && python3 -m analytics.run_all && python3 -m analytics.render_docs`.
"""


def render_memo():
    ex, fc, rc, ms2, dq, mr = R("experiment"), R("forecast_backtest"), R("recovery_checks"), R("margin_sensitivity"), R("dq_evaluation"), R("metrics_reconciliation")
    sh, lt = rc["unlogged_shrink_recovery"], rc["late_supplier_recovery"]
    pw, tr = ex["power_plan"], ex["truth"]
    need = 2 * (1.96 + 0.8416) ** 2 * pw["pre_period_sd_m04_units"] ** 2 / tr["m04_units_per_treated_guest"] ** 2
    base = {x["item"]: x for x in ms2["ranking_by_multiplier"]["1.0"]}
    gm = base["M04 Mango Habanero Gobi"]; gt = base["M04 Gobi Taco"]
    nv, ma7, sm = fc["overall"]["naive"]["WAPE"], fc["overall"]["moving_average_7"]["WAPE"], fc["overall"][fc["best_by_wape"]]["WAPE"]
    return f"""# NASHA operations analytics: executive memo

{BANNER}

**To:** founder. **From:** analytics workstream (P4). **Basis:** a 56-day synthetic operation of three scenario sites, a simulated supply chain, and assumed prices and costs. **Status:** conditional guidance for designing NASHA's data capture and decision rules, not a statement about demand or profit.

## Bottom line

Nothing here measures how NASHA would perform. What the exercise shows is which questions the data model can answer, how reliable the answers are when the truth is known, and what a real operation would need to record. Recommendations are ranked by how well the evidence supports them and each says what would invalidate it.

## Ranked recommendations (all conditional)

1. **Decide the data capture before the first service, not after.** Record receipts with dates, a waste log with reasons, weekly counts and purchase orders from day one. In the simulation, an unlogged 6% shrink on one ingredient was found (rank {sh['rank_most_negative_pairs_with_usage_ge_20kg']} of {sh['pairs_with_usage_ge_20kg']} candidate pairs; ranks across seeds 1 to 5: {', '.join(str(m['rank_of_L03_goat_among_pairs_ge_20kg']) for m in sh['multi_seed_rank_pairs_ge_20kg'])}) *only* because counts, receipts and recipe-based usage existed. *Invalidated if* real counts are too noisy (the simulation used +/-3%) or recipes are far from the placeholders.
2. **Adopt the metric definitions and reconciliation tests as the starting contract** (`metrics.json`: {sum(r['ok'] for r in mr['rows'])} of {len(mr['rows'])} metrics reconcile mart to source). Cheap, and it removes arguments about what a number means. *Invalidated if* the real point-of-sale system cannot supply order-line grain.
3. **Track supplier on-time delivery as a first-class measure.** The query recovered the two suppliers whose lateness was injected (worst two = {', '.join(a for a, _b, _n in lt['observed_on_time_rate_worst_first'][:2])}), from only 21 to 39 deliveries each. *Invalidated if* real delivery windows are not recorded per line.
4. **Use simple forecasts and cover rules, and do not buy forecasting software yet.** On synthetic usage a 7-day average cut error (WAPE) from {nv:.2f} (last day) to {ma7:.2f}, and the best baseline reached {sm:.2f}. Daily usage is noise-dominated, so expect forecast error of this order even with a good model. Pair the forecast with days-of-cover against supplier lead time. *Invalidated if* real demand has strong, stable seasonality, which this data cannot show.
5. **Before changing the menu card for the Mango Habanero Gobi appetizer, size the test.** The simulated placement test (effect: one extra appetizer in 10% of treated guests' orders) needed roughly {need:,.0f} guests per arm for 80% power; with {pw['per_arm']:.0f} per arm its power was about {pct(ex['monte_carlo_with_effect']['metrics']['m04_units']['unadjusted']['reject_rate'], 0)} and the one observed run overstated the effect. Plan the sample from the pre-period variance and pre-register one primary metric. *Invalidated if* the real unit of randomisation is a table or a shift, which changes the variance entirely.
6. **Treat contribution margin as a template.** Under assumed costs the appetizer's margin per unit is ${gm['margin_usd'] / gm['units']:.2f} (new version) vs ${gt['margin_usd'] / gt['units']:.2f} (old taco version), a difference of little consequence; the item ordering was {'stable' if ms2['top3_identical_across_multipliers'] else 'not stable even at the top'} under +/-25% on all costs. Real costs, labour and waste must replace the assumptions before any item decision. *Invalidated by:* real recipe costing, which does not exist yet.

## Risks

- Same-author synthetic evaluation: a clean result mostly proves the code does what its author intended. Example: every injected defect type was detected, while a defect type the author had not injected (timezone slip) was missed entirely.
- Over-reading simulated processes (guest retention, approval funnel, waste rates) as behaviour.
- A volume floor is needed for exception ranking; tiny-quantity ingredients generate false alarms.

## Data needed in a real operation

Point-of-sale order lines with timestamps and voids/returns; item master with dated changes; counts with unit and counter id; receipts and purchase orders with promised and actual dates; waste log with reason; costed recipes; supplier contracts; guest or loyalty identifier only with consent; staffing and opening hours for exposure normalisation.

## NOT CLAIMED

- Any real sales, revenue, margin, cost, demand, price acceptance or customer behaviour. NASHA has none.
- That the appetizer will sell, be profitable, or beat the taco it replaced.
- That the supplier reliability, waste rates, retention or approval rates are real; all are simulated.
- That forecast accuracy transfers to real data.
- That the data-quality rules would work on real data or that recall of 1.0 is meaningful outside this generator.
- Production deployment, users, or any business impact. Nothing here is deployed.

Evidence: `lab/docs/ANALYTICS-EVALUATION.md`, results in `lab/results/analytics/`, reproducible with `python -m analytics.run_all`.
"""


def main():
    os.makedirs(DOCS, exist_ok=True)
    for name, fn in (("ANALYTICS-MART.md", render_mart), ("ANALYTICS-EVALUATION.md", render_eval), ("ANALYTICS-EXEC-MEMO.md", render_memo), ("ANALYTICS-PROSPECTIVE-DESIGN.md", render_prospective)):
        with open(os.path.join(DOCS, name), "w", encoding="utf-8") as f:
            f.write(fn())
    try:
        from . import dashboard
        dashboard.write()
    except ImportError:
        pass
    print("rendered docs")


if __name__ == "__main__":
    main()
